import json, re, sys
from datetime import date
from fractions import Fraction

d = json.load(open(sys.argv[1], encoding='utf-8'))
lines = [l for l in d['export'].split('\n') if l.strip()]

MON = {m: i for i, m in enumerate(['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], 1)}
PLACEHOLDER = {'', 'n/a', '—', 'TBD', '?', '00/00/0000', '00.00.0000', '----/--/--', 'n/k', '-'}

def cut(s):
    return s.strip() if s is not None else ''

def mk(y, m, dd):
    return date(int(y), int(m), int(dd)).isoformat()

rows = []
for l in lines:
    r = {'raw': l}
    if l.startswith('LEDGR;'):
        f = l.split(';')
        r.update(sys='LEDGR', id=int(f[1]), name=f[2], anrede=f[3], dob=f[4], land=f[5], tel=f[6], saldo=f[7], status=f[8], upd=f[9])
    elif l.startswith('ATLAS #'):
        s = [x.strip() for x in l.split(' :: ')]
        r.update(sys='ATLAS', id=int(s[0].split('#')[1]), name=s[1], born=s[2], land=s[3], tel=s[4], owed=s[5], last=s[6], rest=s[7:])
    elif l.startswith('BRIGHTDESK'):
        s = [x.strip() for x in l.split(' | ')]
        kv = {}
        for x in s[1:]:
            k, _, v = x.partition('=')
            kv[k.strip()] = v.strip()
        r.update(sys='BRIGHTDESK', id=int(s[0].split('=')[1]), **kv)
    elif l.startswith('Vendex'):
        r.update(sys='VENDEX', id=int(l.split()[1]))
    elif l.startswith('KOBO/'):
        s = [x.strip() for x in l.split('|')]
        r.update(sys='KOBO', id=int(re.match(r'KOBO/(\d+)', l).group(1)), segs=s)
    elif l.startswith('VERITAS '):
        j = json.loads(l[len('VERITAS '):])
        r.update(sys='VERITAS', id=j['row'], j=j)
    rows.append(r)

def show(r):
    if r['sys'] == 'LEDGR':
        return f"LEDGR {r['id']} | name={r['name']} | anrede={r['anrede']} | dob={r['dob']} | land={r['land']} | tel={r['tel']} | saldo={r['saldo']} | {r['status']} | upd={r['upd']}"
    if r['sys'] == 'ATLAS':
        return f"ATLAS {r['id']} | name={r['name']} | born={r['born']} | land={r['land']} | tel={r['tel']} | owed={r['owed']} | last={r['last']} | rest={r['rest']}"
    if r['sys'] == 'BRIGHTDESK':
        return f"BD {r['id']} | " + ' | '.join(f"{k}={v}" for k, v in r.items() if k not in ('raw','sys','id'))
    if r['sys'] == 'KOBO':
        return f"KOBO {r['id']} | " + ' | '.join(r['segs'])
    if r['sys'] == 'VERITAS':
        return f"VER {r['id']} | " + json.dumps(r['j'], ensure_ascii=False)
    return f"{r['sys']} {r['id']} | {r['raw']}"

for r in rows:
    print(show(r))
print(len(rows), 'rows', file=sys.stderr)

