import unicodedata
def opts(ch):
    if ch in DOUBLE: return DOUBLE[ch]
    if ord(ch) < 128: return [ch]
    d = ''.join(c for c in unicodedata.normalize('NFKD', ch) if not unicodedata.combining(c))
    return [d] if d else [ch]
def variants(s):
    s = s.lower().replace("'", '').replace(' ', '')
    res = {''}
    for ch in s:
        res = {r + o for r in res for o in opts(ch)}
    return res
def giv_variants(g):
    g = g.strip().lower()
    g = NICK.get(g, g)
    return variants(g)
def part_dist(A, B):
    return min(dl(a, b) for a in A for b in B)
def name_dist(x, y):
    return part_dist(giv_variants(x['giv']), giv_variants(y['giv'])) + part_dist(variants(x['fam']), variants(y['fam']))
